import numpy as np
from scipy.optimize import minimize

def solve(n):
    # Maximize sum(x_i * x_{i+2}) subject to x_i + x_{i+1} + x_{i+2} <= 2 and x_i >= 0
    # Objective function: -sum(x_i * x_{i+2})
    def objective(x):
        res = 0
        for i in range(n):
            res += x[i] * x[(i + 2) % n]
        return -res

    # Constraints: x_i + x_{i+1} + x_{i+2} <= 2
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': lambda x, i=i: 2 - (x[i] + x[(i+1)%n] + x[(i+2)%n])})

    # Bounds: 0 <= x_i <= 2
    bounds = [(0, 2) for _ in range(n)]

    # Try several starting points
    best_max = -1
    for start_point in [np.zeros(n), np.ones(n)*0.5, np.ones(n)*0.66, np.random.rand(n)]:
        res = minimize(objective, start_point, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            if -res.fun > best_max:
                best_max = -res.fun
    return best_max

for n in [4, 6, 8, 10, 12]:
    print(f"n={n}, max_sum={solve(n)}")

